/** Padding formulas owned by the Screen component (design.md 2.3); kept as text so the rule is not typed twice. */
export const sizeFormula = {
  bottomPaddingAboveBanner: 'tabBar + (measuredBannerHeight + 2 * bannerPadding, when AdPolicy shows a banner) + 16 + safeAreaBottom',
  bottomPaddingAboveStickyCta: 'ctaHeight + 16 + safeAreaBottom',
} as const;

/** Bottom padding of scroll content above the tab bar and an optional banner strip (M6, N15). */
export function bottomPaddingAboveBanner(measuredBannerHeight: number | null, safeAreaBottom: number): number {
  const strip = measuredBannerHeight == null ? 0 : measuredBannerHeight + 2 * size.bannerPadding;
  return size.tabBar + strip + 16 + safeAreaBottom;
}

/** Bottom padding of scroll content above a sticky CTA that reported its height with onLayout. */
export function bottomPaddingAboveStickyCta(ctaHeight: number, safeAreaBottom: number): number {
  return ctaHeight + 16 + safeAreaBottom;
}
